script:
button { cursor: pointer; }
button:disabled { opacity: 0.45; cursor: not-allowed; }
a, button { transition: opacity 0.15s ease, background 0.15s ease, color 0.15s ease, border-color 0.15s ease; }
a:hover { opacity: 0.7; }
:focus-visible { outline: 2px solid var(--43b5ae6c-cab5-4094-ab96-6170f2e6c33c, #18181B); outline-offset: 2px; }
[data-shop="variant-option"][data-selected="true"] {
	background: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	color: var(--5606e7cf-f76c-4598-b795-d92c7e39fa39, #FFFFFF);
	border-color: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
}
[data-shop="cart-count"][data-empty="true"] { display: none; }
a[data-active="true"] {
	background: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	color: var(--5606e7cf-f76c-4598-b795-d92c7e39fa39, #FFFFFF);
	border-color: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
}
[data-shop="rating-star"] { cursor: pointer; transition: color 0.1s ease; }
[data-shop="rating-star"][data-selected="true"] { color: var(--1cccbee6-3c64-47a2-8e18-339ccc1a58eb, #C2410C); }
input, textarea { font-family: inherit; }
input::placeholder { color: var(--756af8f6-3bcf-4030-b01b-4760b963e8c2, #71717A); }
[data-shop="thumb"][data-selected="true"] { border-color: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B); }
[data-shop="thumb"]:hover { border-color: var(--756af8f6-3bcf-4030-b01b-4760b963e8c2, #71717A); }
[data-shop="cart-drawer"] {
	position: fixed;
	inset: 0;
	z-index: 90;
	pointer-events: none;
}
[data-shop="cart-drawer"] .drawer-backdrop {
	position: absolute;
	inset: 0;
	background: rgba(0, 0, 0, 0.4);
	opacity: 0;
	transition: opacity 0.25s ease;
}
[data-shop="cart-drawer"] .drawer-panel {
	position: absolute;
	top: 0;
	right: 0;
	height: 100%;
	width: min(420px, calc(100vw - 32px));
	background: var(--5606e7cf-f76c-4598-b795-d92c7e39fa39, #FFFFFF);
	color: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	display: flex;
	flex-direction: column;
	transform: translateX(105%);
	transition: transform 0.3s cubic-bezier(0.32, 0.72, 0, 1);
	box-shadow: -16px 0 48px rgba(0, 0, 0, 0.16);
}
[data-shop="cart-drawer"][data-open="true"] { pointer-events: auto; }
[data-shop="cart-drawer"][data-open="true"] .drawer-backdrop { opacity: 1; }
[data-shop="cart-drawer"][data-open="true"] .drawer-panel { transform: translateX(0); }
@media (prefers-reduced-motion: reduce) {
	[data-shop="cart-drawer"] .drawer-backdrop,
	[data-shop="cart-drawer"] .drawer-panel { transition: none; }
}
.drawer-header {
	align-items: center;
	border-bottom: 1px solid var(--faaf07da-6dd1-479e-b766-862cdabc746b, #E4E4E7);
	display: flex;
	flex-shrink: 0;
	justify-content: space-between;
	padding: 18px 24px;
}
.drawer-title { font-size: 15px; font-weight: 600; letter-spacing: -0.01em; }
.drawer-close {
	background: none;
	border: 0;
	color: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	font-size: 22px;
	line-height: 1;
	padding: 2px 6px;
}
.drawer-items { flex: 1; overflow-y: auto; padding: 4px 24px; }
.drawer-item {
	align-items: flex-start;
	border-bottom: 1px solid var(--faaf07da-6dd1-479e-b766-862cdabc746b, #E4E4E7);
	display: flex;
	gap: 14px;
	padding: 18px 0;
}
.drawer-item:last-child { border-bottom: 0; }
.drawer-thumb {
	background: var(--6d034cc9-b213-4a44-a78c-db7be21e983a, #F4F4F5);
	border-radius: 4px;
	flex-shrink: 0;
	height: 64px;
	object-fit: cover;
	width: 64px;
}
.drawer-info { display: flex; flex: 1; flex-direction: column; gap: 3px; min-width: 0; }
.drawer-name {
	color: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	font-size: 13px;
	font-weight: 500;
	line-height: 1.4;
	text-decoration: none;
}
.drawer-rate { color: var(--756af8f6-3bcf-4030-b01b-4760b963e8c2, #71717A); font-size: 12px; }
.drawer-qty { align-items: center; display: flex; gap: 8px; margin-top: 8px; }
.drawer-qty > button {
	align-items: center;
	background: var(--5606e7cf-f76c-4598-b795-d92c7e39fa39, #FFFFFF);
	border: 1px solid var(--faaf07da-6dd1-479e-b766-862cdabc746b, #E4E4E7);
	border-radius: 2px;
	color: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	display: flex;
	font-size: 13px;
	height: 26px;
	justify-content: center;
	width: 26px;
}
.drawer-qty > span { font-size: 13px; min-width: 16px; text-align: center; }
.drawer-qty > .drawer-remove {
	background: none;
	border: 0;
	color: var(--756af8f6-3bcf-4030-b01b-4760b963e8c2, #71717A);
	font-size: 11px;
	height: auto;
	margin-left: 8px;
	padding: 0;
	text-decoration: underline;
	width: auto;
}
.drawer-amount { flex-shrink: 0; font-size: 13px; font-weight: 600; }
.drawer-empty { color: var(--756af8f6-3bcf-4030-b01b-4760b963e8c2, #71717A); font-size: 14px; padding: 40px 0; text-align: center; }
.drawer-footer {
	border-top: 1px solid var(--faaf07da-6dd1-479e-b766-862cdabc746b, #E4E4E7);
	display: flex;
	flex-direction: column;
	flex-shrink: 0;
	gap: 12px;
	padding: 16px 24px 20px;
}
.drawer-total-row {
	display: flex;
	font-size: 14px;
	font-weight: 600;
	justify-content: space-between;
}
.drawer-note { color: var(--756af8f6-3bcf-4030-b01b-4760b963e8c2, #71717A); font-size: 12px; margin-top: -6px; }
.drawer-actions { display: grid; gap: 10px; grid-template-columns: 1fr 1fr; }
.drawer-view, .drawer-checkout {
	border-radius: 2px;
	font-size: 12px;
	font-weight: 700;
	letter-spacing: 0.08em;
	padding: 13px 16px;
	text-align: center;
	text-decoration: none;
	text-transform: uppercase;
}
.drawer-view {
	border: 1px solid var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	color: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
}
.drawer-checkout {
	background: var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	border: 1px solid var(--f32b020d-8d73-41c1-9d55-30c9ee4d15fc, #18181B);
	color: var(--5606e7cf-f76c-4598-b795-d92c7e39fa39, #FFFFFF);
}
.pdp-buybar {
	background: var(--5606e7cf-f76c-4598-b795-d92c7e39fa39, #FFFFFF);
	border-top: 1px solid var(--faaf07da-6dd1-479e-b766-862cdabc746b, #E4E4E7);
	bottom: 0;
	left: 0;
	position: fixed;
	right: 0;
	z-index: 80;
}
.pdp-buybar-inner {
	align-items: center;
	display: flex;
	gap: 16px;
	justify-content: space-between;
	margin: 0 auto;
	max-width: 1200px;
	padding: 10px 40px;
	width: 100%;
}
@media (max-width: 640px) {
	.pdp-buybar-inner { padding: 10px 18px; }
}
#reviews { scroll-margin-top: 24px; }
